     await handlers.settings.setSecret("google_api_key", "synthetic-review-key");
     const file = await document();
-    const workflow = await save([research("research", { document: { fileId: file.id, name: file.name } })]);
-    const queued = await handlers.runs.start(workflow.id); const run = await wait(queued.id);
+    const workflow = await save([
