/** Checked selections from any collecting agent, restricted to the archived content revision. */
export function assessedSelection(record: ResearchRecord): { reviewed: boolean; excerpts: z.infer<typeof Span>[]; tableRows: Set<number> } {
  const reviewed = Object.hasOwn(record.fields ?? {}, ASSESSMENT_FIELD);
  const relevant = sourceAssessments(record).filter((assessment) => assessment.verdict === "relevant");
  const spans = relevant.flatMap((assessment) => assessment.excerpts).sort((a, b) => a.start - b.start || a.end - b.end);
  const excerpts: z.infer<typeof Span>[] = [];
  for (const span of spans) {
    if (span.end <= span.start || span.end > record.text.length) throw new Error("Archived assessment has invalid excerpt bounds.");
    const previous = excerpts.at(-1);
    if (previous && span.start <= previous.end) previous.end = Math.max(previous.end, span.end);
    else excerpts.push({ ...span });
  }
  const tableRows = new Set(relevant.flatMap((assessment) => assessment.tableRows));
  for (const index of tableRows)
    if (!record.table || index >= record.table.rows.length) throw new Error("Archived assessment has an invalid native row.");
  return { reviewed, excerpts, tableRows };
}

