  it("aborts promptly when signal is aborted", async () => {
    const dataset = createSampleDataset();
    const controller = new AbortController();
    controller.abort();

    await expect(
      summarizeResearchDataset(dataset, {
        scope,
        signal: controller.signal,
      }),
    ).rejects.toThrow();
  });

  it("skips records excluded by assessment review", async () => {
    const dataset = createSampleDataset();
    // Mark record 0 as reviewed with NO relevant excerpts or table rows (excluded)
    dataset.records[0]!.fields = {
      ...dataset.records[0]!.fields,
      [ASSESSMENT_FIELD]: [],
    };

    const rows = await summarizeResearchDataset(dataset, {
      scope,
      signal: new AbortController().signal,
    });

    // Record 0 was excluded; only record 1 is returned
    expect(rows).toHaveLength(1);
    expect(rows[0]!.collectedRecordId).toBe(dataset.records[1]!.id);
  });

  it("preserves structured table records using tabular conversion and maintains original metadata", async () => {
    const tableItem = CollectedItem.parse({
      provider: "firecrawl",
      sourceId: "source_specs_1",
      sourceUrl: "https://specs.example.org/dimensions",
      sourceTitle: "BMW 1 Series Technical Specifications",
      publisher: "Specs Portal",
      recordId: "doc_table_1",
      recordType: "table",
      text: "Synthetic native table",
      locator: "spec sheet",
      table: {
        headers: ["Specification", "Value", "Unit"],
        rows: [
          ["Turning Circle", 10.9, "m"],
          ["Boot Volume", 380, "litres"],
        ],
        units: ["m", "litres"],
        footnotes: [],
      },
      metadata: { customEquipmentTag: "chassis-dimensions" },
    });

    const { source, record } = normalizeItem(tableItem, "editorial_reviews", "run_test", at);
    const dataset = ResearchDataset.parse({
      schemaVersion: 1,
      runId: "run_test",
      retrievedAt: at,
      sources: [source],
      records: [record],
      results: [],
      synthetic: true,
    });

    const rows = await summarizeResearchDataset(dataset, {
      scope,
      signal: new AbortController().signal,
    });

    expect(rows).toHaveLength(2);

    // Row 1
    expect(rows[0]!.id).toBe(`${record.id}_row1`);
    expect(rows[0]!.collectedRecordId).toBe(record.id);
    expect(rows[0]!.text).toBe("Specification: Turning Circle; Value: 10.9; Unit: m");
    expect(rows[0]!.locator).toContain("table row 1");
    expect(rows[0]!.table).toEqual({
      ...record.table,
      rows: [["Turning Circle", 10.9, "m"]],
    });
    expect(rows[0]!.fields).toEqual({
      Specification: "Turning Circle",
      Value: 10.9,
      Unit: "m",
    });
    expect(rows[0]!.metadata.customEquipmentTag).toBe("chassis-dimensions");

    // Row 2
    expect(rows[1]!.id).toBe(`${record.id}_row2`);
    expect(rows[1]!.collectedRecordId).toBe(record.id);
    expect(rows[1]!.text).toBe("Specification: Boot Volume; Value: 380; Unit: litres");
    expect(rows[1]!.locator).toContain("table row 2");
    expect(rows[1]!.table).toEqual({
      ...record.table,
      rows: [["Boot Volume", 380, "litres"]],
    });
    expect(rows[1]!.fields).toEqual({
      Specification: "Boot Volume",
      Value: 380,
      Unit: "litres",
    });
    expect(rows[1]!.metadata.customEquipmentTag).toBe("chassis-dimensions");
  });

  it("filters table records to reviewed tableRows when assessment is present", async () => {
    const tableItem = CollectedItem.parse({
      provider: "firecrawl",
      sourceId: "source_specs_1",
      sourceUrl: "https://specs.example.org/dimensions",
      sourceTitle: "BMW 1 Series Technical Specifications",
      publisher: "Specs Portal",
      recordId: "doc_table_1",
      recordType: "table",
      text: "Synthetic native table",
      locator: "spec sheet",
      table: {
        headers: ["Specification", "Value"],
        rows: [
          ["Turning Circle", 10.9],
          ["Unrelated Footnote", 99],
        ],
        units: [],
        footnotes: [],
      },
      metadata: {},
    });

    const { source, record } = normalizeItem(tableItem, "editorial_reviews", "run_test", at);
    const assessment: SourceAssessment = {
      version: 1,
      agentId: "editorial_reviews",
      contentHash: record.contentHash,
      scope: ResearchScope.parse({ model: "1 Series", markets: ["EU"] }),
      runId: "run_test",
      verdict: "relevant",
      reasons: ["Relevant turning circle dimension."],
      uncertainties: [],
      excerpts: [],
      tableRows: [0], // Only row 0 is relevant
      model: "test-model",
    };
    record.fields = {
      ...record.fields,
      [ASSESSMENT_FIELD]: [assessment],
    };

    const dataset = ResearchDataset.parse({
      schemaVersion: 1,
      runId: "run_test",
      retrievedAt: at,
      sources: [source],
      records: [record],
      results: [],
      synthetic: true,
    });

    const rows = await summarizeResearchDataset(dataset, {
      scope,
      signal: new AbortController().signal,
    });

    expect(rows).toHaveLength(1);
    expect(rows[0]!.id).toBe(`${record.id}_row1`);
    expect(rows[0]!.fields).toEqual({ Specification: "Turning Circle", Value: 10.9 });
  });

  it("uses selected excerpts for text extraction rather than whole text when excerpts are present", async () => {
    const rawText =
      "Cookie settings and site banner.\n\n" +
      "The new BMW 120 steering offers remarkable precision and agility on winding roads.\n\n" +
      "Terms of service and footer navigation.";

    const item = CollectedItem.parse({
      provider: "firecrawl",
      sourceId: "source_review_excerpt",
      sourceUrl: "https://auto-review.example.org/bmw-steering",
      sourceTitle: "Steering Review",
      publisher: "Auto Mag",
      recordId: "doc_excerpt",
      recordType: "passage",
      text: rawText,
      locator: "article section",
      metadata: {},
    });

    const { source, record } = normalizeItem(item, "editorial_reviews", "run_test", at);
    const targetExcerpt = "The new BMW 120 steering offers remarkable precision and agility on winding roads.";
    const start = rawText.indexOf(targetExcerpt);
    const end = start + targetExcerpt.length;

    const assessment: SourceAssessment = {
      version: 1,
      agentId: "editorial_reviews",
      contentHash: record.contentHash,
      scope: ResearchScope.parse({ model: "1 Series", markets: ["EU"] }),
      runId: "run_test",
      verdict: "relevant",
      reasons: ["Substantive steering feedback."],
      uncertainties: [],
      excerpts: [{ start, end }],
      tableRows: [],
      model: "test-model",
    };
    record.fields = {
      ...record.fields,
      [ASSESSMENT_FIELD]: [assessment],
    };

    const dataset = ResearchDataset.parse({
      schemaVersion: 1,
      runId: "run_test",
      retrievedAt: at,
      sources: [source],
      records: [record],
      results: [],
      synthetic: true,
    });

    // 1. Offline summarizer uses the excerpt rather than boilerplate
    const offlineRows = await summarizeResearchDataset(dataset, {
      scope,
      signal: new AbortController().signal,
    });

    expect(offlineRows).toHaveLength(1);
    expect(offlineRows[0]!.text).not.toContain("Cookie settings");
    expect(offlineRows[0]!.text).not.toContain("Terms of service");
    expect(offlineRows[0]!.text).toContain("remarkable precision and agility");
    expect(offlineRows[0]!.locator).toContain(`chars ${start + 1}–${end}`);
    expect(offlineRows[0]!.sourceAssessments).toEqual([
      { agentId: "editorial_reviews", verdict: "relevant", model: "test-model" },
    ]);

    // Direct offlineSummarizeRecord also respects assessedSelection
    const directOffline = offlineSummarizeRecord(record, source, scope);
    expect(directOffline.summary).not.toContain("Cookie settings");
    expect(directOffline.summary).toContain("remarkable precision and agility");

    // 2. LLM client receives extracted excerpts in content prompt
    let promptContent = "";
    const mockLlm: LlmClient = {
      generateObject: vi.fn(async (req) => {
        const parsedPrompt = JSON.parse(req.prompt);
        promptContent = parsedPrompt.content;
        return {
          model: "gemini-3.8-flash",
          object: SourceSummariesResult.parse({
            items: [
              {
                brand: "[BMW]",
                salesDescription: "[BMW 1 Series]",
                country: "DE",
                derivate: "F70",
                engineType: "ICE",
                feedbackType: "Likes",
                summary: "Steering dynamics are remarkably agile and precise.",
                vfcLevel2Name: "Handling / Riding",
                vfcLevel3Name: "Like: performance",
              },
            ],
          }),
        };
      }) as unknown as LlmClient["generateObject"],
      generateText: vi.fn(),
    };

    const llmRows = await summarizeResearchDataset(dataset, {
      llm: mockLlm,
      scope,
      signal: new AbortController().signal,
    });

    expect(promptContent).toBe(targetExcerpt);
    expect(promptContent).not.toContain("Cookie settings");
    expect(llmRows).toHaveLength(1);
    expect(llmRows[0]!.locator).toContain(`chars ${start + 1}–${end}`);
  });
});

